// ====== Utilidades ======
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtF = d => { if(!d) return ''; const [y,m,dd]=String(d).slice(0,10).split('-'); return `${dd}/${m}/${y.slice(2)}`; };
const fmtFH = ts => { if(!ts) return ''; const d=new Date(ts); return d.toLocaleDateString('es-ES',{day:'2-digit',month:'2-digit',year:'2-digit'})+' '+d.toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}); };
const hoyISO = () => { const d=new Date(); return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10); };
function toast(msg, err){ document.querySelectorAll('.toast').forEach(x=>x.remove()); const t=document.createElement('div'); t.className='toast'+(err?' err':''); t.textContent=msg; document.body.appendChild(t); setTimeout(()=>t.remove(), err?4200:2600); }
async function rpc(fn, args={}){
  let r;
  try{
    r = await fetch(`${SB_URL}/rest/v1/rpc/${fn}`, {method:'POST', headers:{apikey:SB_KEY, Authorization:'Bearer '+SB_KEY, 'Content-Type':'application/json'}, body:JSON.stringify(args)});
  }catch(e){ throw new Error('Sin conexión. Revisa la cobertura e inténtalo de nuevo.'); }
  const txt = await r.text();
  if(!r.ok){
    let m=''; try{ m=JSON.parse(txt).message||''; }catch(e){ m=txt; }
    if(m==='SESION'){ salir(true); }
    if(!ERR[m]&&r.status!==401&&window.reportarError) reportarError(new Error('rpc '+fn+': '+String(m).slice(0,300)));
    throw new Error(ERR[m] || m || ('Error '+r.status));
  }
  return txt ? JSON.parse(txt) : null;
}
function busy(btn, on){ if(!btn) return; if(on){ btn.dataset.t=btn.innerHTML; btn.innerHTML='<span class="spin"></span>'; btn.disabled=true; } else { btn.innerHTML=btn.dataset.t||btn.innerHTML; btn.disabled=false; } }
function barra(title, left, right){
  return `<div class="top">${left||''}<h1>${esc(title)}</h1>${right||''}</div>`;
}
function view(html){ $('#app').innerHTML = html; window.scrollTo(0,0); }

// ====== Voz (para quien no lee bien) ======
let hablando=false;
function textoLectura(tb){
  const p=[tb.compromiso, tb.cuerpo||'', (tb.puntos||[]).length?'Puntos para hablar. '+tb.puntos.join(' '):'', tb.tema||'', tb.tema_intro||'', (tb.tema_puntos||[]).join('. ')];
  return p.filter(Boolean).join('. ').replace(/https?:\/\/\S+/g,'');
}
function hablar(btn, texto){
  if(!('speechSynthesis' in window)){ toast('Este móvil no puede leer en voz alta', true); return; }
  if(hablando){ speechSynthesis.cancel(); hablando=false; btn.textContent='Escuchar'; return; }
  const u=new SpeechSynthesisUtterance(texto); u.lang='es-ES'; u.rate=.95;
  const v=speechSynthesis.getVoices().find(v=>/^es(-|_)ES/i.test(v.lang)); if(v) u.voice=v;
  u.onend=u.onerror=()=>{hablando=false; btn.textContent='Escuchar';};
  speechSynthesis.cancel(); speechSynthesis.speak(u); hablando=true; btn.textContent='Parar';
}
function pararVoz(){ if(hablando && 'speechSynthesis' in window){ speechSynthesis.cancel(); hablando=false; } }

// ====== Login ======
async function pantallaLogin(){
  pararVoz();
  view(barra('Toolbox HSE') + `<div class="wrap"><div class="card"><b>¿Quién eres?</b><div class="muted small">Entra con el mismo PIN de la app de limpieza.</div></div><div id="ll" class="empty"><span class="spin dk"></span></div></div>`);
  try{
    const l = await rpc('lista_trabajadores');
    $('#ll').outerHTML = `<div class="login-list">${l.map(w=>`<button class="who ${w.rol==='admin'?'admin':''}" data-id="${esc(w.id)}" data-n="${esc(w.nombre)}">${esc(w.nombre)}</button>`).join('')}</div>`;
    document.querySelectorAll('.who').forEach(b=>b.onclick=()=>pantallaPin(b.dataset.id, b.dataset.n));
  }catch(e){ $('#ll').innerHTML = `<p>${esc(e.message)}</p><button class="btn sec" onclick="pantallaLogin()">Reintentar</button>`; }
}
function pantallaPin(id, nombre){
  let pin='';
  view(barra(nombre, `<button class="ib" id="bk">‹</button>`) + `<div class="wrap"><div class="card" style="text-align:center"><b>Escribe tu PIN</b><div class="pin-dots" id="dots"></div><div id="perr" class="small" style="color:var(--bad);min-height:20px"></div>
    <div class="pad">${[1,2,3,4,5,6,7,8,9].map(n=>`<button data-k="${n}">${n}</button>`).join('')}<button data-k="del">⌫</button><button data-k="0">0</button><button data-k="ok" style="background:var(--navy);color:#fff">✓</button></div></div></div>`);
  $('#bk').onclick=pantallaLogin;
  const pinta=()=>{ $('#dots').innerHTML = Array.from({length:Math.max(4,pin.length)},(_,i)=>`<i class="${i<pin.length?'f':''}"></i>`).join(''); };
  pinta();
  const enviar = async ()=>{
    if(pin.length<4) return;
    $('#perr').textContent='';
    try{
      const r = await rpc('entrar',{p_id:id, p_pin:pin});
      if(r.error){ pin=''; pinta(); $('#perr').textContent = ERR[r.error]||r.error; return; }
      S.tok=r.token; S.yo=r.yo; ls.set('limp.tok', r.token); ls.set('limp.yo', JSON.stringify(r.yo)); inicio();
    }catch(e){ pin=''; pinta(); $('#perr').textContent=e.message; }
  };
  document.querySelectorAll('.pad button').forEach(b=>b.onclick=()=>{
    const k=b.dataset.k;
    if(k==='del') pin=pin.slice(0,-1); else if(k==='ok') return enviar(); else if(pin.length<8) pin+=k;
    pinta();
  });
}
async function salir(silencioso){
  const t=S.tok; S.tok=null; S.yo=null; ls.set('limp.tok', null); ls.set('limp.yo', null);
  if(t && !silencioso){ try{ await rpc('salir',{p_tok:t}); }catch(e){} }
  pantallaLogin();
}

function volverLimpieza(){ pararVoz(); location.href='limpieza.html'; }

// ====== Inicio ======
async function inicio(){
  // Misma sesión que la app de limpieza (mismo sitio web)
  if(!S.tok){ S.tok = ls.get('limp.tok'); }
  if(!S.tok) return pantallaLogin();
  try{
    S.yo = await rpc('yo',{p_tok:S.tok});
  }catch(e){ if(S.tok){ view(barra('Toolbox HSE')+`<div class="wrap"><div class="card">${esc(e.message)}<br><br><button class="btn sec" onclick="inicio()">Reintentar</button></div></div>`); } return; }
  // Enlace directo a un mes (desde el aviso del móvil o el botón de la app de limpieza)
  let a=null,m=null,f=null; try{ const q=new URLSearchParams(location.search); a=+q.get('a')||null; m=+q.get('m')||null; f=q.get('f'); S._d=q.get('d'); if(q.get('s')==='form') S.seccion='form'; history.replaceState(null,'',location.pathname); }catch(e){}
  const dq=new URLSearchParams(location.search).get('d')||S._d;
  if(dq && /^[0-9a-f-]{36}$/i.test(dq)){ if(S.yo.rol==='admin'){ S.seccion='docs'; return pantallaDocDetalle(dq); } if(S.yo.encargado) return pantallaEncDoc(dq); return pantallaDocLeer(dq); }
  if(f && /^[0-9a-f-]{36}$/i.test(f)){ if(S.yo.rol==='admin'){ S.seccion='form'; return pantallaFormDetalle(f); } return pantallaFormLeer(f); }
  if(a&&m){ S.anio=a; return S.yo.rol==='admin' ? pantallaMes(m) : pantallaLeer(a,m); }
  if(S.yo.rol==='admin') return pantallaAnio();
  if(S.yo.encargado) return pantallaEncargado();
  return pantallaOperario();
}

