function htmlLectura(tb){
  const parr = (tb.cuerpo||'').split('\n').filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
  const intro = (tb.tema_intro||'').split('\n').filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
  const link = s => esc(s).replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener">$1</a>');
  return `<div class="card read">
    ${tb.imagen?`<img class="hero" src="${tb.imagen}" alt="">`:''}
    <div class="compromiso">${esc(tb.compromiso)}</div>${parr}
    ${(tb.puntos||[]).length?`<div class="qs"><b>Puntos para hablar</b>${tb.puntos.map(q=>`<div>• ${esc(q)}</div>`).join('')}</div>`:''}
  </div>
  ${tb.tema?`<div class="card read"><div class="tema">${esc(tb.tema)}</div>${intro}<ul>${(tb.tema_puntos||[]).map(x=>`<li>${link(x)}</li>`).join('')}</ul></div>`:''}`;
}

async function pantallaLeer(anio, mes){
  view(barra(`Toolbox de ${MESES[mes-1]}`, `<button class="ib" id="bk">‹</button>`, `<button class="ib" id="voz">Escuchar</button>`) + `<div class="wrap" id="w"><div class="empty"><span class="spin dk"></span></div></div>`);
  $('#bk').onclick=pantallaOperario;
  let d;
  try{ d = await rpc('prl_mes',{p_tok:S.tok,p_anio:anio,p_mes:mes}); }catch(e){ $('#w').innerHTML=`<div class="card">${esc(e.message)}</div>`; return; }
  const tb=d.toolbox, mia=d.firmas.find(f=>f.trabajador===S.yo.id);
  $('#voz').onclick=e=>hablar(e.currentTarget, textoLectura(tb));
  let h = htmlLectura(tb);
  if(mia){
    h += `<div class="card done"><div class="big">✓</div><h3 style="margin:10px 0 4px">Firmado</h3><div class="muted small">${fmtFH(mia.firmado_en)}</div>${mia.firma?`<img src="${mia.firma}" style="max-height:70px;margin-top:10px">`:''}</div>`;
    $('#w').innerHTML=h; return;
  }
  if(d.sesion && d.sesion.estado==='cerrada'){ $('#w').innerHTML = h+`<div class="card">Este mes ya está cerrado.</div>`; return; }
  h += `<div class="card"><b>Tu firma</b>
    <label class="check"><input type="checkbox" id="leido"><span>He leído (o me han explicado) este Toolbox y lo he entendido.</span></label>
    <div class="sigbox" id="sb"><canvas></canvas><div class="sigline"></div><div class="ph">Firma aquí con el dedo</div></div>
    <div class="row" style="margin-top:8px"><span class="small muted grow">${esc(S.yo.nombre)}</span><button class="btn ghost" id="borra">Borrar</button></div>
  </div><div style="height:70px"></div>
  <div class="sticky-act"><div><button class="btn big ok" id="firmar" disabled>Firmar</button></div></div>`;
  $('#w').innerHTML=h;
  const pad = sigPad($('#sb'));
  const upd=()=>{ $('#firmar').disabled = !($('#leido').checked && !pad.vacio()); };
  pad.onchange=upd; $('#leido').onchange=upd;
  $('#borra').onclick=()=>{pad.limpiar(); upd();};
  $('#firmar').onclick=async e=>{
    const b=e.currentTarget; busy(b,true);
    try{
      await rpc('prl_firmar',{p_tok:S.tok,p_anio:anio,p_mes:mes,p_trab:S.yo.id,p_puesto:null,p_firma:pad.png()});
      pararVoz(); toast('¡Firmado! Gracias.'); pantallaLeer(anio, mes);
    }catch(err){ busy(b,false); toast(err.message,true); }
  };
}

